struct PulseScreenBackground: View {
    @Environment(\.pulseVisualTheme) private var visualTheme

    @ViewBuilder
    var body: some View {
        if visualTheme == .tideArchive {
            LinearGradient(
                colors: [PulseDesign.archiveSky, PulseDesign.archiveSkyDeep],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()
        } else {
            PulseDesign.background
                .ignoresSafeArea()
        }
    }
}

enum PulseFieldPresentation {
    case standard
    case today
}

struct PulseFieldBackground: View {
    var presentation: PulseFieldPresentation = .standard
    var isCompleted = false
    var allowsMotion = true

    @Environment(\.horizontalSizeClass) private var horizontalSizeClass
    @Environment(\.pulseVisualTheme) private var visualTheme
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.scenePhase) private var scenePhase

    @ViewBuilder
    var body: some View {
        if visualTheme == .tideArchive {
            archiveField
        } else if visualTheme == .editorialJournal {
            Color.clear
        } else {
            quietField
        }
    }

    private var quietField: some View {
        TimelineView(.animation(
            minimumInterval: PulseDesign.ambientFieldMinimumInterval,
            paused: !allowsAmbientMotion
        )) { timeline in
            GeometryReader { proxy in
                let usesRegularWidthGeometry = horizontalSizeClass == .regular
                let phase = ambientPhase(at: timeline.date)
                let counterPhase = ambientPhase(
                    at: timeline.date.addingTimeInterval(PulseDesign.ambientFieldCycleDuration * 0.37)
                )

                PulseAmbientFieldCanvas(
                    size: proxy.size,
                    widthRatio: usesRegularWidthGeometry
                        ? PulseDesign.regularWidthFieldWidthRatio
                        : PulseDesign.fieldWidthRatio,
                    heightRatio: usesRegularWidthGeometry
                        ? PulseDesign.regularWidthFieldHeightRatio
                        : PulseDesign.fieldHeightRatio,
                    ringInset: usesRegularWidthGeometry
                        ? PulseDesign.regularWidthFieldRingInset
                        : PulseDesign.fieldRingInset,
                    verticalPositionRatio: usesRegularWidthGeometry
                        ? PulseDesign.regularWidthFieldVerticalPositionRatio
                        : PulseDesign.fieldVerticalPositionRatio,
                    phase: phase,
                    counterPhase: counterPhase,
                    showsFlowLayer: presentation == .today
                )
            }
        }
        .mask {
            LinearGradient(
                stops: [
                    .init(color: .clear, location: 0),
                    .init(color: .black, location: PulseDesign.fieldFadeInEndRatio),
                    .init(
                        color: .black,
                        location: horizontalSizeClass == .regular
                            ? PulseDesign.regularWidthFieldFadeStartRatio
                            : PulseDesign.fieldFadeStartRatio
                    ),
                    .init(
                        color: .clear,
                        location: horizontalSizeClass == .regular
                            ? PulseDesign.regularWidthFieldFadeEndRatio
                            : PulseDesign.fieldFadeEndRatio
                    )
                ],
                startPoint: .top,
                endPoint: .bottom
            )
            .ignoresSafeArea()
        }
        .ignoresSafeArea()
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    private var archiveField: some View {
        TimelineView(.animation(
            minimumInterval: PulseDesign.ambientFieldMinimumInterval,
            paused: !allowsAmbientMotion
        )) { timeline in
            GeometryReader { proxy in
                let phase = ambientPhase(at: timeline.date)
                let counterPhase = ambientPhase(
                    at: timeline.date.addingTimeInterval(
                        PulseDesign.ambientFieldCycleDuration * 0.41
                    )
                )

                PulseArchiveFieldCanvas(
                    size: proxy.size,
                    phase: phase,
                    counterPhase: counterPhase,
                    presentation: presentation,
                    isCompleted: isCompleted
                )
                .animation(
                    allowsAmbientMotion
                        ? .smooth(duration: PulseDesign.archiveRiseDuration)
                        : nil,
                    value: isCompleted
                )
            }
        }
        .ignoresSafeArea()
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    private var allowsAmbientMotion: Bool {
        allowsMotion && !reduceMotion && scenePhase == .active
    }

    private func ambientPhase(at date: Date) -> Double {
        guard allowsAmbientMotion else { return 0 }
        let progress = date.timeIntervalSinceReferenceDate
            .truncatingRemainder(dividingBy: PulseDesign.ambientFieldCycleDuration)
            / PulseDesign.ambientFieldCycleDuration
        return progress * 2 * .pi
    }
}

private struct PulseArchiveHorizonGeometry {
    let verticalBias: CGFloat
    let drift: CGFloat
    let phase: Double

    func addCurve(to path: inout Path, in rect: CGRect) {
        let motion = CGFloat(sin(phase)) * drift
        let counterMotion = CGFloat(cos(phase * 0.73)) * drift
        let left = CGPoint(x: rect.minX, y: rect.height * (verticalBias + motion * 0.34))
        let center = CGPoint(
            x: rect.midX,
            y: rect.height * (verticalBias - drift * 0.72 + counterMotion * 0.22)
        )
        let right = CGPoint(
            x: rect.maxX,
            y: rect.height * (verticalBias + drift * 0.38 - motion * 0.24)
        )

        path.move(to: left)
        path.addCurve(
            to: center,
            control1: CGPoint(x: rect.width * 0.18, y: left.y + rect.height * drift * 0.54),
            control2: CGPoint(x: rect.width * 0.35, y: center.y - rect.height * drift * 0.46)
        )
        path.addCurve(
            to: right,
            control1: CGPoint(x: rect.width * 0.66, y: center.y + rect.height * drift * 0.38),
            control2: CGPoint(x: rect.width * 0.84, y: right.y - rect.height * drift * 0.42)
        )
    }
}

private struct PulseArchiveTideShape: Shape {
    let geometry: PulseArchiveHorizonGeometry

    func path(in rect: CGRect) -> Path {
        var path = Path()
        geometry.addCurve(to: &path, in: rect)
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
        path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
        path.closeSubpath()
        return path
    }
}

private struct PulseArchiveHorizonLine: Shape {
    let geometry: PulseArchiveHorizonGeometry

    func path(in rect: CGRect) -> Path {
        var path = Path()
        geometry.addCurve(to: &path, in: rect)
        return path
    }
}

private struct PulseArchiveFieldCanvas: View {
    let size: CGSize
    let phase: Double
    let counterPhase: Double
    let presentation: PulseFieldPresentation
    let isCompleted: Bool

    var body: some View {
        ZStack {
            PulseArchiveTideShape(geometry: PulseArchiveHorizonGeometry(
                verticalBias: min(0.90, waterlineRatio + 0.12),
                drift: PulseDesign.archiveSurfaceDrift * 0.52,
                phase: counterPhase
            ))
            .fill(PulseDesign.archiveNight.opacity(0.92))

            PulseArchiveTideShape(geometry: PulseArchiveHorizonGeometry(
                verticalBias: waterlineRatio,
                drift: PulseDesign.archiveSurfaceDrift,
                phase: phase
            ))
            .fill(
                LinearGradient(
                    colors: [PulseDesign.archiveTide, PulseDesign.archiveDepth],
                    startPoint: .top,
                    endPoint: .bottom
                )
            )

            PulseArchiveHorizonLine(geometry: PulseArchiveHorizonGeometry(
                verticalBias: waterlineRatio,
                drift: PulseDesign.archiveSurfaceDrift,
                phase: phase
            ))
            .stroke(
                PulseDesign.archiveMist.opacity(0.72),
                style: StrokeStyle(lineWidth: PulseDesign.emphasisLineWidth, lineCap: .round)
            )
        }
        .frame(width: size.width, height: size.height)
    }

    private var waterlineRatio: CGFloat {
        let baseRatio = presentation == .today
            ? PulseDesign.archiveTodayWaterlineRatio
            : PulseDesign.archiveStandardWaterlineRatio
        guard presentation == .today, isCompleted else { return baseRatio }
        return baseRatio - PulseDesign.archiveCompletionRiseRatio
    }
}

private struct PulseAmbientFieldCanvas: View {
    let size: CGSize
    let widthRatio: CGFloat
    let heightRatio: CGFloat
    let ringInset: CGFloat
    let verticalPositionRatio: CGFloat
    let phase: Double
    let counterPhase: Double
    let showsFlowLayer: Bool

    var body: some View {
        ZStack {
            if showsFlowLayer {
                flowBands
            }
            upperFlowLine
            contours
            lowerFlowLine
        }
    }

    private var opacityMultiplier: Double {
        showsFlowLayer ? PulseDesign.todayFieldOpacityMultiplier : 1
    }

    private var flowBands: some View {
        ZStack {
            PulseFieldFlowBand(verticalBias: 0.30, thickness: 0.075, direction: 1)
                .fill(PulseDesign.field.opacity(PulseDesign.todayFlowBandBaseOpacity * 0.72))
            PulseFieldFlowBand(verticalBias: 0.40, thickness: 0.090, direction: -1)
                .fill(PulseDesign.field.opacity(PulseDesign.todayFlowBandBaseOpacity))
            PulseFieldFlowBand(verticalBias: 0.50, thickness: 0.105, direction: 1)
                .fill(PulseDesign.grass.opacity(PulseDesign.todayFlowBandBaseOpacity * 0.72))
        }
        .scaleEffect(x: 1.02 + CGFloat(sin(phase)) * 0.006, y: 1, anchor: .center)
        .offset(
            x: CGFloat(cos(counterPhase)) * PulseDesign.todayFlowBandDrift,
            y: CGFloat(sin(phase)) * PulseDesign.ambientFieldVerticalDrift * 0.85
        )
    }

    private var upperFlowLine: some View {
        PulseFieldFlowLine(verticalBias: 0.34)
            .stroke(
                PulseDesign.field.opacity(PulseDesign.fieldBandOpacity * opacityMultiplier),
                style: StrokeStyle(lineWidth: PulseDesign.thinLineWidth, lineCap: .round)
            )
            .offset(
                x: CGFloat(cos(counterPhase))
                    * PulseDesign.ambientFieldHorizontalDrift * 0.45,
                y: CGFloat(sin(counterPhase))
                    * PulseDesign.ambientFieldVerticalDrift * 0.55
            )
    }

    private var contours: some View {
        ZStack {
            Ellipse()
                .stroke(
                    PulseDesign.field.opacity(PulseDesign.fieldOutlineOpacity * opacityMultiplier),
                    lineWidth: PulseDesign.emphasisLineWidth
                )
                .frame(width: size.width * widthRatio, height: size.height * heightRatio)

            ForEach(1...PulseDesign.fieldRingCount, id: \.self) { ring in
                PulseFieldContourRing(
                    size: size,
                    widthRatio: widthRatio,
                    heightRatio: heightRatio,
                    ringInset: ringInset,
                    ring: ring,
                    opacityMultiplier: opacityMultiplier
                )
            }
        }
        .scaleEffect(1 + CGFloat(sin(phase)) * PulseDesign.ambientFieldBreathAmplitude)
        .rotationEffect(.degrees(
            sin(counterPhase) * PulseDesign.ambientFieldRotationAmplitude
        ))
        .offset(
            x: CGFloat(sin(counterPhase)) * PulseDesign.ambientFieldHorizontalDrift,
            y: CGFloat(cos(phase)) * PulseDesign.ambientFieldVerticalDrift
        )
        .position(x: size.width / 2, y: size.height * verticalPositionRatio)
    }

    private var lowerFlowLine: some View {
        PulseFieldFlowLine(verticalBias: 0.57)
            .stroke(
                PulseDesign.field.opacity(
                    PulseDesign.fieldBandOpacity * 0.72 * opacityMultiplier
                ),
                style: StrokeStyle(lineWidth: PulseDesign.thinLineWidth, lineCap: .round)
            )
            .offset(
                x: -CGFloat(sin(phase)) * PulseDesign.ambientFieldHorizontalDrift * 0.55,
                y: CGFloat(cos(counterPhase)) * PulseDesign.ambientFieldVerticalDrift * 0.7
            )
    }
}

private struct PulseFieldContourRing: View {
    let size: CGSize
    let widthRatio: CGFloat
    let heightRatio: CGFloat
    let ringInset: CGFloat
    let ring: Int
    let opacityMultiplier: Double

    var body: some View {
        Ellipse()
            .stroke(
                PulseDesign.field.opacity(ringOpacity),
                lineWidth: PulseDesign.fieldBandWidth
            )
            .frame(width: ringWidth, height: ringHeight)
    }

    private var ringOpacity: Double {
        (PulseDesign.fieldBandOpacity - Double(ring - 1) * 0.025) * opacityMultiplier
    }

    private var ringWidth: CGFloat {
        max(0, size.width * widthRatio - CGFloat(ring) * ringInset)
    }

    private var ringHeight: CGFloat {
        max(0, size.height * heightRatio - CGFloat(ring) * ringInset)
    }
}

private struct PulseFieldFlowLine: Shape {
    let verticalBias: CGFloat

    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX - rect.width * 0.08, y: rect.height * verticalBias))
        path.addCurve(
            to: CGPoint(x: rect.maxX + rect.width * 0.08, y: rect.height * (verticalBias + 0.03)),
            control1: CGPoint(x: rect.width * 0.24, y: rect.height * (verticalBias - 0.12)),
            control2: CGPoint(x: rect.width * 0.68, y: rect.height * (verticalBias + 0.15))
        )
        return path
    }
}

private struct PulseFieldFlowBand: Shape {
    let verticalBias: CGFloat
    let thickness: CGFloat
    let direction: CGFloat

    func path(in rect: CGRect) -> Path {
        var path = Path()
        let upperStart = rect.height * verticalBias
        let upperEnd = rect.height * (verticalBias + 0.018 * direction)
        let lowerStart = rect.height * (verticalBias + thickness)
        let lowerEnd = rect.height * (verticalBias + thickness - 0.015 * direction)

        path.move(to: CGPoint(x: rect.minX - rect.width * 0.08, y: upperStart))
        path.addCurve(
            to: CGPoint(x: rect.maxX + rect.width * 0.08, y: upperEnd),
            control1: CGPoint(
                x: rect.width * 0.28,
                y: rect.height * (verticalBias - 0.055 * direction)
            ),
            control2: CGPoint(
                x: rect.width * 0.68,
                y: rect.height * (verticalBias + 0.070 * direction)
            )
        )
        path.addLine(to: CGPoint(x: rect.maxX + rect.width * 0.08, y: lowerEnd))
        path.addCurve(
            to: CGPoint(x: rect.minX - rect.width * 0.08, y: lowerStart),
            control1: CGPoint(
                x: rect.width * 0.70,
                y: rect.height * (verticalBias + thickness + 0.050 * direction)
            ),
            control2: CGPoint(
                x: rect.width * 0.25,
                y: rect.height * (verticalBias + thickness - 0.040 * direction)
            )
        )
        path.closeSubpath()
        return path
    }
}

struct PulseOpenRing: View {
    let color: Color
    var lineWidth: CGFloat = PulseDesign.checkInRingLineWidth

    var body: some View {
        Circle()
            .trim(from: 0, to: PulseDesign.checkInRingTrim)
            .stroke(
                color,
                style: StrokeStyle(lineWidth: lineWidth, lineCap: .butt)
            )
            .rotationEffect(.degrees(PulseDesign.checkInRingRotationDegrees))
            .accessibilityHidden(true)
    }
}

struct PulseBrandMark: View {
    var size: CGFloat = PulseDesign.brandMarkSize
    @Environment(\.pulseVisualTheme) private var visualTheme

    @ViewBuilder
    var body: some View {
        if visualTheme == .tideArchive {
            Circle()
                .fill(PulseDesign.archiveDepth)
                .overlay {
                    Image("PulseMark")
                        .resizable()
                        .renderingMode(.template)
                        .foregroundStyle(PulseDesign.archiveForeground)
                }
                .overlay {
                    Circle()
                        .stroke(
                            PulseDesign.archiveCopper,
                            lineWidth: PulseDesign.emphasisLineWidth
                        )
                }
                .frame(width: size, height: size)
                .accessibilityHidden(true)
        } else {
            RoundedRectangle(cornerRadius: PulseDesign.brandMarkCornerRadius, style: .continuous)
                .fill(PulseDesign.action)
                .overlay {
                    Image("PulseMark")
                        .resizable()
                        .renderingMode(.template)
                        .foregroundStyle(PulseDesign.actionForeground)
                }
                .frame(width: size, height: size)
                .accessibilityHidden(true)
        }
    }
}

struct PulseAppHeader: View {
    let source: PulsePrimarySection

    @Environment(\.dynamicTypeSize) private var dynamicTypeSize

    var body: some View {
        HStack(spacing: PulseDesign.spacing8) {
            PulseBrandMark()

            Text("today.navigation_title")
                .font(.subheadline.weight(.medium))
                .foregroundStyle(PulseDesign.ink)
                .lineLimit(1)

            Spacer(minLength: PulseDesign.spacing16)

            if dynamicTypeSize.isAccessibilitySize {
                NavigationLink(value: PulseNavigationDestination.settings) {
                    Image(systemName: "gearshape")
                        .font(.title2.weight(.semibold))
                        .foregroundStyle(PulseDesign.ink)
                        .frame(
                            minWidth: PulseDesign.minimumHitTarget,
                            minHeight: PulseDesign.minimumHitTarget
                        )
                }
                .accessibilityLabel("settings.navigation_title")
                .accessibilityIdentifier("settings.navigation.open.\(source.rawValue)")
            } else {
                NavigationLink(value: PulseNavigationDestination.settings) {
                    Text("settings.navigation_title")
                        .font(.subheadline.weight(.semibold))
                        .foregroundStyle(PulseDesign.ink)
                        .frame(
                            minWidth: PulseDesign.minimumHitTarget,
                            minHeight: PulseDesign.minimumHitTarget
                        )
                }
                .accessibilityLabel("settings.navigation_title")
                .accessibilityIdentifier("settings.navigation.open.\(source.rawValue)")
            }
        }
        .frame(maxWidth: PulseDesign.screenMaxWidth)
        .frame(minHeight: PulseDesign.topBarHeight)
        .padding(.horizontal, PulseDesign.horizontalPadding)
        .frame(maxWidth: .infinity)
    }
}

struct PulseSecondaryNavigationBackButton: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.pulseVisualTheme) private var visualTheme

    var body: some View {
        Button {
            dismiss()
        } label: {
            Label {
                Text("navigation.back")
            } icon: {
                Image(systemName: "chevron.backward")
            }
            .foregroundStyle(PulseDesign.appAccent(for: visualTheme))
        }
        .accessibilityIdentifier("navigation.back")
    }
}

private struct PulseSecondaryNavigationModifier: ViewModifier {
    let isEnabled: Bool

    func body(content: Content) -> some View {
        content
            .navigationBarBackButtonHidden(isEnabled)
            .toolbar {
                if isEnabled {
                    ToolbarItem(placement: .topBarLeading) {
                        PulseSecondaryNavigationBackButton()
                    }
                }
            }
    }
}

extension View {
    func pulseSecondaryNavigation(isEnabled: Bool = true) -> some View {
        modifier(PulseSecondaryNavigationModifier(isEnabled: isEnabled))
    }
}
